import React, { useState, useEffect } from "react";
import toast from "react-hot-toast";
import { FiPlus, FiEdit2, FiTrash2, FiX, FiCheck } from "react-icons/fi";
import { useNavigate } from "react-router-dom";
import DeleteModal from "../../Modals/DeleteModal";

const DeliveryTab = ({ activeSub }) => {
  const [currentSubTab, setCurrentSubTab] = useState("delivery-zones");
  const navigate = useNavigate();

  useEffect(() => {
    if (activeSub === "delivery-zones") setCurrentSubTab("delivery-zones");
    else if (activeSub === "delivery-settings") setCurrentSubTab("delivery-settings");
  }, [activeSub]);

  // Delivery Zones Mock State
  const [zones, setZones] = useState(() => {
    const saved = localStorage.getItem("delivery_zones");
    if (saved) return JSON.parse(saved);
    return [
      { id: 1, locality: "Indiranagar", pincodes: "560038, 560008", time: "24 Hours", charge: 30, status: "Active" },
      { id: 2, locality: "Whitefield", pincodes: "560066, 560048", time: "48 Hours", charge: 50, status: "Active" },
      { id: 3, locality: "Jayanagar", pincodes: "560011, 560041", time: "24 Hours", charge: 30, status: "Active" },
    ];
  });

  useEffect(() => {
    localStorage.setItem("delivery_zones", JSON.stringify(zones));
  }, [zones]);

  // Delivery Settings Mock State
  const [settings, setSettings] = useState({
    pickupEnabled: true,
    deliveryEnabled: true,
    defaultTime: "24 Hours",
    defaultCharge: "40",
  });

  // Modal State
  const [showZoneModal, setShowZoneModal] = useState(false);
  const [editingZoneId, setEditingZoneId] = useState(null);
  const [zoneForm, setZoneForm] = useState({
    locality: "",
    pincodes: "",
    time: "24 Hours",
    charge: "",
    status: "Active",
  });

  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [selectedZoneIdForDelete, setSelectedZoneIdForDelete] = useState(null);
  const [selectedZoneLocalityForDelete, setSelectedZoneLocalityForDelete] = useState("");

  const handleOpenAdd = () => {
    setEditingZoneId(null);
    setZoneForm({
      locality: "",
      pincodes: "",
      time: "24 Hours",
      charge: "40",
      status: "Active",
    });
    setShowZoneModal(true);
  };

  const handleOpenEdit = (zone) => {
    setEditingZoneId(zone.id);
    setZoneForm({
      locality: zone.locality,
      pincodes: zone.pincodes,
      time: zone.time,
      charge: zone.charge.toString(),
      status: zone.status,
    });
    setShowZoneModal(true);
  };

  const handleOpenDelete = (zone) => {
    setSelectedZoneIdForDelete(zone.id);
    setSelectedZoneLocalityForDelete(zone.locality);
    setShowDeleteModal(true);
  };

  const handleConfirmDelete = () => {
    if (selectedZoneIdForDelete) {
      setZones(zones.filter((z) => z.id !== selectedZoneIdForDelete));
      toast.success("Delivery zone deleted.");
    }
    setShowDeleteModal(false);
    setSelectedZoneIdForDelete(null);
    setSelectedZoneLocalityForDelete("");
  };

  const handleZoneSubmit = (e) => {
    e.preventDefault();
    if (editingZoneId) {
      setZones(
        zones.map((z) =>
          z.id === editingZoneId
            ? {
                ...z,
                locality: zoneForm.locality,
                pincodes: zoneForm.pincodes,
                time: zoneForm.time,
                charge: Number(zoneForm.charge) || 0,
                status: zoneForm.status,
              }
            : z
        )
      );
      toast.success("Delivery zone updated.");
    } else {
      const newZone = {
        id: Date.now(),
        locality: zoneForm.locality,
        pincodes: zoneForm.pincodes,
        time: zoneForm.time,
        charge: Number(zoneForm.charge) || 0,
        status: zoneForm.status,
      };
      setZones([...zones, newZone]);
      toast.success("Delivery zone added.");
    }
    setShowZoneModal(false);
  };

  const handleSaveSettings = (e) => {
    e.preventDefault();
    toast.success("Delivery settings saved successfully.");
  };

  return (
    <div className="delivery-tab animate-fade-in">
      
      {/* Sub tabs selectors */}
      <div className="d-flex justify-content-between align-items-center flex-wrap mb-4 gap-3">
        <h3 style={{ fontSize: "20px", fontWeight: "800", color: "#0F172A", margin: 0 }}>
          Delivery Management
        </h3>
        <div
          className="d-flex gap-1.5 p-1 rounded-3 w-100 w-sm-auto"
          style={{
            backgroundColor: "#F1F5F9",
            overflowX: "auto",
            WebkitOverflowScrolling: "touch",
            scrollbarWidth: "none",
          }}
        >
          <button
            onClick={() => navigate("/seller-dashboard/delivery-zones")}
            className="flex-grow-1 flex-sm-grow-0 text-center"
            style={{
              border: "none",
              background: currentSubTab === "delivery-zones" ? "#ffffff" : "transparent",
              color: currentSubTab === "delivery-zones" ? "#A847F0" : "#64748B",
              padding: "8px 16px",
              borderRadius: "6px",
              fontSize: "13px",
              fontWeight: "700",
              boxShadow: currentSubTab === "delivery-zones" ? "0 1px 3px rgba(0,0,0,0.05)" : "none",
              cursor: "pointer",
              transition: "all 0.2s",
              whiteSpace: "nowrap",
            }}
          >
            Delivery Zones
          </button>
          <button
            onClick={() => navigate("/seller-dashboard/delivery-settings")}
            className="flex-grow-1 flex-sm-grow-0 text-center"
            style={{
              border: "none",
              background: currentSubTab === "delivery-settings" ? "#ffffff" : "transparent",
              color: currentSubTab === "delivery-settings" ? "#A847F0" : "#64748B",
              padding: "8px 16px",
              borderRadius: "6px",
              fontSize: "13px",
              fontWeight: "700",
              boxShadow: currentSubTab === "delivery-settings" ? "0 1px 3px rgba(0,0,0,0.05)" : "none",
              cursor: "pointer",
              transition: "all 0.2s",
              whiteSpace: "nowrap",
            }}
          >
            Delivery Settings
          </button>
        </div>
      </div>

      {currentSubTab === "delivery-zones" && (
        <div className="dashboard-card p-3 p-sm-4">
          <div className="d-flex justify-content-between align-items-center mb-3">
            <h4 style={{ fontSize: "16px", fontWeight: "700", color: "#0F172A", margin: 0 }}>
              Configured Delivery Locality Zones ({zones.length})
            </h4>
            <button
              onClick={handleOpenAdd}
              className="btn btn-main pill btn-sm d-flex align-items-center gap-1"
              style={{ fontSize: "12px", padding: "6px 14px" }}
            >
              <FiPlus size={14} /> Add Zone
            </button>
          </div>

          <div className="table-responsive">
            <table className="table align-middle">
              <thead className="table-light">
                <tr style={{ fontSize: "12px", color: "#475569", fontWeight: "700" }}>
                  <th>Locality Name</th>
                  <th>Covered Pincodes</th>
                  <th>Delivery ETA</th>
                  <th>Extra Delivery Charges</th>
                  <th>Status</th>
                  <th className="text-center">Actions</th>
                </tr>
              </thead>
              <tbody>
                {zones.map((zone) => (
                  <tr key={zone.id} style={{ fontSize: "13px", color: "#334155" }}>
                    <td className="fw-700">{zone.locality}</td>
                    <td className="small text-muted">{zone.pincodes}</td>
                    <td>{zone.time}</td>
                    <td className="fw-700">₹{zone.charge}</td>
                    <td>
                      <span className="badge rounded-pill bg-success-subtle text-success px-2.5 py-1">
                        {zone.status}
                      </span>
                    </td>
                    <td>
                      <div className="d-flex gap-2 justify-content-center">
                        <button onClick={() => handleOpenEdit(zone)} className="btn-action btn-approve" title="Edit Zone">
                          <FiEdit2 size={13} />
                        </button>
                        <button onClick={() => handleOpenDelete(zone)} className="btn-action btn-reject" title="Delete Zone">
                          <FiTrash2 size={13} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {currentSubTab === "delivery-settings" && (
        <div className="dashboard-card p-3 p-sm-4">
          <h4 style={{ fontSize: "16px", fontWeight: "700", color: "#0F172A", marginBottom: "20px" }}>
            Global Store Delivery Options
          </h4>

          <form onSubmit={handleSaveSettings}>
            <div className="row gy-4">
              
              <div className="col-md-6">
                <div className="p-3 bg-light rounded-3 d-flex align-items-center justify-content-between">
                  <div>
                    <strong className="text-heading d-block font-15">Enable Store Pickup</strong>
                    <span className="text-muted small">Allow buyers to collect orders in person</span>
                  </div>
                  <div className="form-check form-switch fs-4">
                    <input
                      className="form-check-input shadow-none cursor-pointer"
                      type="checkbox"
                      checked={settings.pickupEnabled}
                      onChange={(e) => setSettings({ ...settings, pickupEnabled: e.target.checked })}
                    />
                  </div>
                </div>
              </div>

              <div className="col-md-6">
                <div className="p-3 bg-light rounded-3 d-flex align-items-center justify-content-between">
                  <div>
                    <strong className="text-heading d-block font-15">Enable Door Delivery</strong>
                    <span className="text-muted small">Provide home/office dispatch shipping options</span>
                  </div>
                  <div className="form-check form-switch fs-4">
                    <input
                      className="form-check-input shadow-none cursor-pointer"
                      type="checkbox"
                      checked={settings.deliveryEnabled}
                      onChange={(e) => setSettings({ ...settings, deliveryEnabled: e.target.checked })}
                    />
                  </div>
                </div>
              </div>

              <div className="col-md-6">
                <label className="form-label fw-600 text-heading small mb-1">Default Delivery Time</label>
                  <select
                    className="form-select border shadow-none"
                    style={{ height: "46px", borderRadius: "8px", fontSize: "14px" }}
                    value={settings.defaultTime}
                    onChange={(e) => setSettings({ ...settings, defaultTime: e.target.value })}
                  >
                    {Array.from({ length: 24 }, (_, i) => {
                      const hours = i + 1;
                      const label = hours === 1 ? "1 Hour" : `${hours} Hours`;
                      return (
                        <option key={hours} value={label}>
                          {label}
                        </option>
                      );
                    })}
                    <option value="48 Hours">48 Hours</option>
                    <option value="3-5 Days">3-5 Days</option>
                  </select>
              </div>

              <div className="col-md-6">
                <label className="form-label fw-600 text-heading small mb-1">Default Delivery Charge (₹)</label>
                <input
                  type="number"
                  required
                  className="common-input border"
                  value={settings.defaultCharge}
                  onChange={(e) => setSettings({ ...settings, defaultCharge: e.target.value })}
                />
              </div>

              <div className="col-12 text-end">
                <button type="submit" className="btn btn-main pill px-5 mt-2">
                  Save Delivery Settings
                </button>
              </div>

            </div>
          </form>
        </div>
      )}

      {/* ZONE MODAL (ADD / EDIT) */}
      {showZoneModal && (
        <div className="dashboard-modal-overlay">
          <div className="dashboard-modal-content">
            <div className="d-flex justify-content-between align-items-center mb-4 pb-2 border-bottom">
              <h4 className="mb-0 text-heading fw-800">
                {editingZoneId ? "Modify Delivery Zone" : "Register Delivery Zone"}
              </h4>
              <button onClick={() => setShowZoneModal(false)} className="btn-close-modal">
                <FiX size={20} />
              </button>
            </div>

            <form onSubmit={handleZoneSubmit}>
              <div className="row gy-3">
                <div className="col-12">
                  <label className="form-label fw-700 text-heading mb-1 small">Locality Name</label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. Koramangala"
                    className="common-input border"
                    value={zoneForm.locality}
                    onChange={(e) => setZoneForm({ ...zoneForm, locality: e.target.value })}
                  />
                </div>

                <div className="col-12">
                  <label className="form-label fw-700 text-heading mb-1 small">Covered Pincodes (comma separated)</label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. 560095, 560034"
                    className="common-input border"
                    value={zoneForm.pincodes}
                    onChange={(e) => setZoneForm({ ...zoneForm, pincodes: e.target.value })}
                  />
                </div>

                <div className="col-sm-6">
                  <label className="form-label fw-700 text-heading mb-1 small">Delivery ETA</label>
                  <select
                    className="form-select border shadow-none"
                    style={{ height: "46px", borderRadius: "8px", fontSize: "14px" }}
                    value={zoneForm.time}
                    onChange={(e) => setZoneForm({ ...zoneForm, time: e.target.value })}
                  >
                    {Array.from({ length: 24 }, (_, i) => {
                      const hours = i + 1;
                      const label = hours === 1 ? "1 Hour" : `${hours} Hours`;
                      return (
                        <option key={hours} value={label}>
                          {label}
                        </option>
                      );
                    })}
                    <option value="48 Hours">48 Hours</option>
                    <option value="3-5 Days">3-5 Days</option>
                  </select>
                </div>

                <div className="col-sm-6">
                  <label className="form-label fw-700 text-heading mb-1 small">Delivery Fee (₹)</label>
                  <input
                    type="number"
                    required
                    className="common-input border"
                    value={zoneForm.charge}
                    onChange={(e) => setZoneForm({ ...zoneForm, charge: e.target.value })}
                  />
                </div>

                <div className="col-12">
                  <label className="form-label fw-700 text-heading mb-1 small">Zone Status</label>
                  <select
                    className="form-select border shadow-none"
                    style={{ height: "46px", borderRadius: "8px", fontSize: "14px" }}
                    value={zoneForm.status}
                    onChange={(e) => setZoneForm({ ...zoneForm, status: e.target.value })}
                  >
                    <option value="Active">Active</option>
                    <option value="Inactive">Inactive</option>
                  </select>
                </div>

              </div>

              <div className="d-flex justify-content-end gap-2 mt-4 pt-3 border-top">
                <button
                  type="button"
                  onClick={() => setShowZoneModal(false)}
                  className="btn btn-light pill px-4"
                >
                  Cancel
                </button>
                <button type="submit" className="btn btn-main pill px-4">
                  {editingZoneId ? "Update Zone" : "Confirm Zone"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      <DeleteModal
        open={showDeleteModal}
        title="Delete Delivery Zone?"
        message={`Are you sure you want to delete the delivery zone for ${selectedZoneLocalityForDelete}?`}
        itemName={selectedZoneLocalityForDelete}
        onClose={() => setShowDeleteModal(false)}
        onConfirm={handleConfirmDelete}
      />

      <style>{`
        .dashboard-modal-overlay {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background-color: rgba(15, 23, 42, 0.6);
          backdrop-filter: blur(4px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 9999;
          padding: 15px;
        }
        .dashboard-modal-content {
          background-color: #ffffff;
          border-radius: 16px;
          width: 100%;
          max-width: 520px;
          padding: 28px;
          box-shadow: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
        }
        .btn-close-modal {
          border: none;
          background: none;
          color: #64748B;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 4px;
          border-radius: 6px;
          transition: all 0.2s;
        }
        .btn-close-modal:hover {
          background-color: #F1F5F9;
          color: #0F172A;
        }
        .common-input {
          width: 100%;
          height: 46px;
          border-radius: 8px;
          padding: 0 16px;
          font-size: 14px;
          color: #0F172A;
          outline: none;
          box-shadow: none;
        }
      `}</style>

    </div>
  );
};

export default DeliveryTab;
